do $s$ declare a jsonb := $j$[["ar-letters","يتعرف الطفل على شكل الحرف ويسميه ويميزه عن غيره.","أتعرف على الحروف وأسميها.",["يشير إلى حرف اسمه","يطابق الحرف بحرف مثله"]],["ar-letter-sound","يربط الطفل الحرف بصوته ويستمع إلى أول صوت في الكلمة.","أعرف صوت كل حرف.",["يذكر كلمة تبدأ بحرف الباء","يطابق الحرف بصورة تبدأ به"]],["ar-vocab","ينمّي الطفل مفرداته ويستعمل كلمات جديدة في كلامه.","أتعلم كلمات جديدة وأستعملها.",["يسمي أشياء من الصور","يستعمل كلمة جديدة في جملة"]],["ar-word-build","يكوّن الطفل كلمات وجملًا بسيطة مناسبة لمرحلته.","أكتب كلمة وجملة قصيرة.",["يرتب حروفًا لتكوين كلمة","يكتب جملة من ثلاث كلمات"]],["ar-express","يعبّر الطفل عن فكرته بكلمات واضحة شفهيًا أو كتابيًا.","أحكي فكرتي بكلماتي.",["يحكي ما رسمه","يصف مشروعه بجمل قصيرة"]],["ar-reading","يقرأ الطفل نصوصًا قصيرة مناسبة لمرحلته بصوت واضح.","أقرأ كلمات وجملًا قصيرة.",["يقرأ جملة تحت صورة","يقرأ فقرة قصيرة بمساعدة"]],["c-sequence","يرتب الطفل الأحداث أو الخطوات بحسب تسلسلها.","أرتب ما حدث أولًا ثم ثانيًا.",["يرتب صور قصة","يرتب خطوات روتين الصباح"]],["c-visual","يميز الطفل بين الأشياء بالنظر: الألوان والأشكال والفروق الصغيرة.","أنظر جيدًا وأميز بين الأشياء.",["يطابق لونين متشابهين","يجد الصورة المختلفة"]],["c-problem","يحاول الطفل إيجاد حل بسيط لمشكلة تواجهه.","أجرب حلًا عندما أواجه مشكلة.",["يجرب طريقتين لتثبيت المجسم","يطلب المساعدة عند الحاجة"]],["c-attention","ينتبه الطفل لما يعمل عليه مدة مناسبة لعمره.","أنتبه لما أعمل.",["يتابع نشاطًا قصيرًا حتى نهايته"]],["cr-draw","يعبّر الطفل بالرسم والتلوين ويستعمل الألوان بحرية.","أرسم وألوّن ما أحب.",["يرسم صورة من خياله","يلوّن بالأصابع"]],["cr-form","يركّب الطفل أشكالًا ويشكّل منها تكوينات جديدة.","أركّب أشكالًا لأصنع شيئًا جديدًا.",["يلصق أشكالًا ليكوّن حيوانًا"]],["cr-ideas","يبتكر الطفل أفكارًا بسيطة جديدة.","أفكر في فكرة جديدة.",["يبتكر اسمًا وصفة لشخصية"]],["cr-story","يتخيل الطفل أحداث قصة ويرويها.","أتخيل قصة وأحكيها.",["يخترع نهاية لقصة"]],["cr-design","يصمم الطفل عملًا فنيًا ويرتب عناصره بطريقة جميلة.","أصمم عملًا وأرتب عناصره.",["يصمم بطاقة شكر","يصنع مجسمًا من علبة"]],["l-routine","يتعرف الطفل على روتينه اليومي ويتابعه.","أعرف ما أفعله كل يوم.",["يتابع جدول يومه","يعلّم العادة التي أنجزها"]],["l-tidy","يرتب الطفل أدواته وألعابه في أماكنها.","أرتب أدواتي في مكانها.",["يعيد الألعاب إلى الصندوق"]],["l-independ","يقوم الطفل بمهام مناسبة لعمره بنفسه.","أنجز بعض أعمالي بنفسي.",["يجهز حقيبته بنفسه"]],["l-instructions","يتبع الطفل خطوات أو تعليمات بسيطة بالترتيب.","أتبع الخطوات واحدة بعد الأخرى.",["ينفذ مشروعًا بحسب الخطوات"]],["l-coop","يتعاون الطفل مع ولي الأمر أو المعلم أو زملائه.","أتعاون مع من حولي.",["يشارك ولي أمره في تنفيذ خطوة"]],["m-count","يعد الطفل الأشياء ويعرف عددها.","أعد الأشياء.",["يعد الأشكال في الصورة","يعد مرات إنجاز عادته"]],["m-number-recog","يتعرف الطفل على الأعداد ويقرؤها.","أتعرف على الأرقام.",["يشير إلى الرقم المطلوب"]],["m-qty-match","يطابق الطفل بين العدد والكمية التي يمثلها.","أربط الرقم بعدد الأشياء.",["يضع ثلاث بطاقات أمام الرقم ٣"]],["m-compare","يقارن الطفل بين الكميات أو الأطوال أو الأحجام.","أقارن بين شيئين.",["يحدد الأطول والأقصر","يقارن عددين"]],["m-order","يرتب الطفل الأعداد أو الأشياء ترتيبًا مناسبًا.","أرتب الأعداد والأشياء.",["يرتب العصي من الأقصر إلى الأطول"]],["m-shapes","يتعرف الطفل على الأشكال الهندسية ويسميها.","أعرف الأشكال وأسميها.",["يسمي المثلث والدائرة","يبحث عن أشكال حوله"]],["m-patterns","يكتشف الطفل نمطًا متكررًا ويكمله.","أكمل النمط المتكرر.",["يكمل نمطًا من ثلاثة ألوان"]],["m-addsub","يجمع الطفل ويطرح أعدادًا مناسبة لمرحلته.","أجمع وأطرح أعدادًا صغيرة.",["يحسب ثمن شيئين في المتجر"]],["m-problems","يحل الطفل مسائل بسيطة من حياته اليومية.","أحل مسألة من حياتي اليومية.",["يحسب عدد الصحون اللازمة"]],["m-multdiv","يستعمل الطفل الضرب والقسمة الأساسيين في مواقف بسيطة.","أستعمل الضرب في مواقف بسيطة.",["يحسب كم صحنًا لعدة أشخاص"]],["mo-eyehand","ينسّق الطفل بين عينه ويده أثناء الأعمال اليدوية.","أنسق بين عيني ويدي.",["يضع بصمة في المكان المطلوب"]],["mo-cut","يقص الطفل ويلصق بأمان وبإشراف مناسب.","أقص وألصق بأمان مع الكبار.",["يقص شكلًا بمقص آمن"]],["s-observe","يلاحظ الطفل ما حوله ويصف ما يراه ويسجله.","ألاحظ وأصف ما أرى.",["يصف تغير النبتة","يسجل حالة الطقس"]],["s-classify","يصنف الطفل الأشياء حسب صفة مشتركة.","أصنف الأشياء حسب صفاتها.",["يصنف الأشكال أو الألعاب","يفرز المواد للتدوير"]],["s-compare","يقارن الطفل بين الأشياء ويذكر أوجه الشبه والاختلاف.","أقارن وأذكر الشبه والاختلاف.",["يقارن ظلين"]],["s-living","يتعرف الطفل على الكائنات الحية وبيئاتها.","أتعرف على الكائنات الحية.",["يربط الحيوان ببيئته","يلاحظ نمو نبتة"]],["s-nature","يفهم الطفل مفاهيم الطبيعة الأساسية ويحافظ على البيئة.","أفهم الطبيعة وأحافظ عليها.",["يشرح كيف نوفر الماء"]],["s-explore","يجرب الطفل تجربة آمنة ويتوقع ثم يلاحظ.","أجرب وأتوقع وأرى النتيجة.",["يتوقع هل يطفو الشيء أم يغرق"]],["s-body","يتعرف الطفل على أجزاء جسمه وحواسه.","أتعرف على جسمي وحواسي.",["يسمي الحاسة المستعملة"]]]$j$::jsonb; b jsonb := $j$[["pj_ara01","ar-letters","main","يتعرف على شكل الحرف ويسميه"],["pj_ara01","ar-letter-sound","support","يربط الحرف بصوته عند نطقه"],["pj_ara02","ar-letter-sound","main","يربط صوت الحرف بصورة تبدأ به"],["pj_ara02","ar-letters","support","يطابق الحرف بالصورة المناسبة"],["pj_ara02","ar-vocab","support","يتعلم أسماء الصور"],["pj_ara03","ar-vocab","main","يجمع كلمات جديدة ويرتبها في قاموسه"],["pj_ara03","ar-word-build","support","يكتب جملة قصيرة بالكلمة"],["pj_ara04","ar-express","main","يحكي قصته بكلماته"],["pj_ara04","c-sequence","main","يرتب أحداث القصة"],["pj_ara04","cr-story","support","يتخيل أحداث القصة"],["pj_ara05","ar-vocab","main","يتعلم كلمات جديدة ويستعملها"],["pj_ara05","ar-word-build","support","يستعمل الكلمة في جملة"],["pj_art01","cr-draw","main","يعبّر بالألوان واللمس"],["pj_art01","mo-eyehand","support","ينسق بين عينه ويده عند البصم"],["pj_art01","c-visual","support","يميز بين الألوان"],["pj_art02","cr-form","main","يركّب أشكالًا مختلفة ليصنع تكوينًا"],["pj_art02","m-shapes","support","يتعرف على الأشكال التي يستعملها"],["pj_art02","mo-cut","support","يقص بأمان بإشراف الكبار"],["pj_art03","cr-design","main","يصمم بطاقة ويرتب عناصرها"],["pj_art03"