pj_mo_plant","s-observe","main","يلاحظ نمو النبتة ويسجل ما يراه"],["pj_mo_plant","m-compare","support","يقارن أطوال النبتة بين الأيام"],["pj_mo_plant","s-compare","support","يقارن بين ما لاحظه في أيام مختلفة"],["pj_mo_reuse","l-instructions","main","ينفذ مشروعه خطوة بخطوة"],["pj_mo_reuse","s-explore","support","يجرب استعمال مادة بطريقة جديدة"],["pj_mo_reuse","cr-design","support","يصمم شيئًا جديدًا من مواد مستعملة"],["pj_nat01","s-nature","main","يفهم أهمية الماء وكيف نحافظ عليه"],["pj_nat01","cr-design","support","يصمم ملصقًا يرتب عناصره"],["pj_nat01","ar-express","support","يكتب عبارة قصيرة تدعو لترشيد الماء"],["pj_nat02","s-classify","main","يفرز الأشياء حسب مادتها"],["pj_nat02","s-nature","support","يتعرف على فكرة التدوير"],["pj_nat02","m-count","support","يعد ما فرزه"],["pj_nat03","s-nature","main","يتعرف على معنى البيئة النظيفة"],["pj_nat03","s-compare","support","يقارن بين بيئة نظيفة وغير نظيفة"],["pj_nat03","ar-express","support","يصف ما يراه بجمل"],["pj_sci01","s-observe","main","يلاحظ تغيّر الحبة مع الأيام"],["pj_sci01","s-living","support","يتعرف على أجزاء النبات"],["pj_sci01","c-sequence","support","يرتب مراحل النمو"],["pj_sci02","s-observe","main","يسجل ملاحظاته عن النبتة"],["pj_sci02","m-compare","support","يقارن بين الأطوال المسجلة"],["pj_sci03","s-explore","main","يتوقع ثم يجرب ويلاحظ"],["pj_sci03","s-classify","support","يصنف الأشياء إلى تطفو وتغرق"],["pj_sci03","s-observe","support","يلاحظ ما يحدث في الماء"],["pj_sci04","s-classify","main","يصنف الأشياء حسب صفاتها"],["pj_sci04","s-observe","support","يصف الأشياء بحواسه"],["pj_sci04","m-count","support","يعد الأشياء في كل مجموعة"],["pj_sci05","s-observe","main","يلاحظ كيف يتغير الظل"],["pj_sci05","s-compare","support","يقارن بين ظلين"],["pj_sci05","cr-draw","support","يرسم ما لاحظه"],["pj_sci06","s-observe","main","يلاحظ الطقس ويسجله"],["pj_sci06","m-count","support","يعد الأيام المشمسة والغائمة"],["pj_sci06","s-nature","support","يتعرف على حالات الطقس"],["pj_sci07","s-living","main","يربط الحيوان ببيئته"],["pj_sci07","s-classify","support","يصنف الحيوانات حسب مكان عيشها"],["pj_sci07","cr-draw","support","يرسم الحيوان في بيئته"],["pj_sci08","s-body","main","يتعرف على حواسه ويسميها"],["pj_sci08","c-attention","support","ينتبه لما يلمسه"],["pj_sci09","c-visual","main","يميز الألوان ويطابقها"],["pj_sci09","ar-vocab","support","يتعلم أسماء الألوان"],["pj_wk_book","ar-word-build","main","يكتب كلمة تحت كل صورة"],["pj_wk_book","cr-draw","support","يرسم صور الكلمات"],["pj_wk_book","ar-reading","support","يقرأ كلماته بصوت واضح"],["pj_wk_numbers","m-count","main","يعد المجموعات"],["pj_wk_numbers","m-compare","support","يقارن بين المجموعات"],["pj_wk_numbers","m-number-recog","support","يتعرف على الأرقام"],["pj_wk_shapes","m-shapes","main","يسمي الأشكال حوله"],["pj_wk_shapes","s-classify","support","يصنف الأشكال"],["pj_wk_shapes","cr-form","support","يركب الأشكال ليصنع صورة"]]$j$::jsonb; x jsonb; begin
for x in select * from jsonb_array_elements(a) loop
 insert into skill_info(skill_id,goal,goal_kid,examples,status) select id,x->>1,x->>2,array(select jsonb_array_elements_text(x->3)),'draft' from skills where slug=x->>0 on conflict (skill_id) do nothing; end loop;
for x in select * from jsonb_array_elements(b) loop
 insert into proj_skills(project,skill_id,role,goal,ord,status) select x->>0,s.id,x->>2,x->>3,0,'draft' from skills s join proj_items j on j.slug=x->>0 and j.kind='project' where s.slug=x->>1 and s.levels && j.levels on conflict (project,skill_id) do nothing; end loop;
end $s$;